export default function LojaScreen() {
  const [pesquisa, setPesquisa] = useState('');
  const [categoriaSel, setCategoriaSel] = useState('Todas');
  const [cep, setCep] = useState('');
  const [resultadoFrete, setResultadoFrete] = useState<null | {
    pac: string;
    sedex: string;
    prazoPac: string;
    prazoSedex: string;
  }>(null);

  
  const produtosFiltrados = PRODUTOS.filter((p) => {
    const combinaCategoria =
      categoriaSel === 'Todas' || p.categoria === categoriaSel;
    const combinaBusca = p.nome
      .toLowerCase()
      .includes(pesquisa.toLowerCase());
    return combinaCategoria && combinaBusca;
  });

  
  const calcularFrete = () => {
    const cepLimpo = cep.replace(/\D/g, '');
    if (cepLimpo.length !== 8) {
      Alert.alert('CEP Inválido', 'Digite um CEP válido com 8 dígitos.');
      return;
    }

    setResultadoFrete({
      pac: 'R$ 18,90',
      prazoPac: '5 a 8 dias úteis',
      sedex: 'R$ 32,50',
      prazoSedex: '2 a 3 dias úteis',
    });
  };

  return (
    <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
      {}
      <View style={styles.header}>
        <View>
          <Text style={styles.headerTitle}>Loja BeeTech 🍯</Text>

        </View>
        <TouchableOpacity style={styles.cartButton}>
          <MaterialCommunityIcons name="cart-outline" size={24} color={COLORS.primary} />
        </TouchableOpacity>
      </View>

      {}
      <View style={styles.searchContainer}>
        <MaterialCommunityIcons name="magnify" size={22} color={COLORS.textMuted} />
        <TextInput
          style={styles.searchInput}
          placeholder="Buscar caixas, atrativos, cera..."
          placeholderTextColor={COLORS.textMuted}
          value={pesquisa}
          onChangeText={setPesquisa}
        />
        {pesquisa !== '' && (
          <TouchableOpacity onPress={() => setPesquisa('')}>
            <MaterialCommunityIcons name="close-circle" size={18} color={COLORS.textMuted} />
          </TouchableOpacity>
        )}
      </View>

      {}
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.categoriesContainer}
      >
        {CATEGORIAS.map((cat) => (
          <TouchableOpacity
            key={cat}
            style={[
              styles.categoryChip,
              categoriaSel === cat && styles.categoryChipActive,
            ]}
            onPress={() => setCategoriaSel(cat)}
          >
            <Text
              style={[
                styles.categoryText,
                categoriaSel === cat && styles.categoryTextActive,
              ]}
            >
              {cat}
            </Text>
          </TouchableOpacity>
        ))}
      </ScrollView>

      {}
      <View style={styles.freteCard}>
        <View style={styles.freteHeader}>
          <MaterialCommunityIcons name="truck-delivery-outline" size={22} color={COLORS.primary} />
          <Text style={styles.freteTitle}>Calcular Frete e Entrega</Text>
        </View>

        <View style={styles.freteInputContainer}>
          <TextInput
            style={styles.freteInput}
            placeholder="Digite seu CEP (ex: 80000-000)"
            placeholderTextColor={COLORS.textMuted}
            keyboardType="numeric"
            maxLength={9}
            value={cep}
            onChangeText={setCep}
          />
          <TouchableOpacity style={styles.freteButton} onPress={calcularFrete}>
            <Text style={styles.freteButtonText}>Calcular</Text>
          </TouchableOpacity>
        </View>

        {resultadoFrete && (
          <View style={styles.freteResultado}>
            <View style={styles.freteOpcao}>
              <View>
                <Text style={styles.freteNome}>Entrega Normal (PAC)</Text>
                <Text style={styles.fretePrazo}>{resultadoFrete.prazoPac}</Text>
              </View>
              <Text style={styles.freteValor}>{resultadoFrete.pac}</Text>
            </View>

            <View style={[styles.freteOpcao, { borderTopWidth: 1, borderColor: COLORS.border, paddingTop: 8 }]}>
              <View>
                <Text style={styles.freteNome}>Entrega Expressa (SEDEX)</Text>
                <Text style={styles.fretePrazo}>{resultadoFrete.prazoSedex}</Text>
              </View>
              <Text style={styles.freteValor}>{resultadoFrete.sedex}</Text>
            </View>

            <Text style={styles.freteGratisAviso}>
              💡 Frete GRÁTIS para compras acima de R$ 150,00!
            </Text>
          </View>
        )}
      </View>

      {}
      <Text style={styles.sectionTitle}>
        Produtos Disponíveis ({produtosFiltrados.length})
      </Text>

      <View style={styles.productsGrid}>
        {produtosFiltrados.map((item) => (
          <View key={item.id} style={styles.productCard}>
            <Image source={{ uri: item.imagem }} style={styles.productImage} />

            <View style={styles.badgeCategory}>
              <Text style={styles.badgeText}>{item.categoria}</Text>
            </View>

            <View style={styles.productInfo}>
              <Text style={styles.productName} numberOfLines={2}>
                {item.nome}
              </Text>

              <View style={styles.ratingRow}>
                <MaterialCommunityIcons name="star" size={16} color="#F59E0B" />
                <Text style={styles.ratingText}>{item.avaliacao}</Text>
              </View>

              <Text style={styles.productDesc} numberOfLines={2}>
                {item.descricao}
              </Text>

              <View style={styles.productFooter}>
                <Text style={styles.productPrice}>
                  R$ {item.preco.toFixed(2).replace('.', ',')}
                </Text>

                <TouchableOpacity
                  style={styles.addButton}
                  onPress={() => Alert.alert('Sucesso', `${item.nome} adicionado ao carrinho!`)}
                >
                  <MaterialCommunityIcons name="plus" size={20} color="#FFF" />
                </TouchableOpacity>
              </View>
            </View>
          </View>
        ))}
      </View>
    </ScrollView>
  );
}

